// Plockar ut nyckeltal ur BRREG:s regnskapsregister.
// Svaren paras ihop med orgnr från föregående nod, samma ordning, 1:1.

const source = $('AS med händelser').all();
const responses = $input.all();

if (source.length === 0 || responses.length === 0) {
  return [];
}

// En rad per (orgnr, år). Bolagsräkenskapen vinner över koncernräkenskapen.
const byKey = new Map();
let noAccounts = 0;
let serverErrors = 0;

for (let i = 0; i < responses.length; i++) {
  const orgnr = String(source[i]?.json?.orgnr ?? '').trim();
  if (!orgnr) continue;

  const res = responses[i]?.json ?? {};
  const status = Number(res.statusCode);

  if (status === 404 || status === 410) {
    // Normalt för nystartade eller vilande bolag. Inte ett fel.
    noAccounts++;
    continue;
  }

  if (status >= 500) {
    serverErrors++;
    continue;
  }

  if (status !== 200) continue;

  const body = res.body;
  const statements = Array.isArray(body) ? body : (body ? [body] : []);

  for (const entry of statements) {
    const tilDato = String(entry?.regnskapsperiode?.tilDato ?? '');
    const year = parseInt(tilDato.slice(0, 4), 10);
    if (Number.isNaN(year)) continue;

    const resultat = entry?.resultatregnskapResultat ?? {};
    const drift = resultat?.driftsresultat ?? {};

    const row = {
      orgnr: orgnr,
      year: year,
      currency: entry?.valuta ?? 'NOK',
      revenue: drift?.driftsinntekter?.sumDriftsinntekter ?? null,
      ebit: drift?.driftsresultat ?? null,
      net_result: resultat?.aarsresultat ?? null,
      equity: entry?.egenkapitalGjeld?.egenkapital?.sumEgenkapital ?? null,
      debt: entry?.egenkapitalGjeld?.gjeldOversikt?.sumGjeld ?? null,
      assets: entry?.eiendeler?.sumEiendeler ?? null,
      raw: JSON.stringify(entry)
    };

    const key = orgnr + '|' + year;
    const isSelskap = String(entry?.regnskapstype ?? '').toUpperCase() === 'SELSKAP';
    const existing = byKey.get(key);

    if (!existing || (isSelskap && !existing.isSelskap)) {
      byKey.set(key, { row: row, isSelskap: isSelskap });
    }
  }
}

if (serverErrors > 0 && serverErrors === responses.length) {
  throw new Error('Samtliga ' + serverErrors + ' anrop mot regnskapsregisteret gav 5xx. Avbryter körningen.');
}

console.log('regnskap: ' + responses.length + ' orgnr in, ' + byKey.size + ' rader ut, ' + noAccounts + ' utan räkenskaper, ' + serverErrors + ' serverfel');

const out = [];
for (const value of byKey.values()) {
  out.push({ json: value.row });
}
return out;
